{"hypotheses": [
{"name": "Composite1", "mechanism": "Firms with high accruals and low book-to-market ratios tend to have poor future returns, while firms with low accruals and high book-to-market ratios tend to have high future returns. Combining these factors can help identify mispriced stocks.", "expression": {"terms": [{"weight": 1.0, "primitive": "Accruals"}, {"weight": -1.0, "primitive": "BM"}], "regime": null, "vol_target": true}, "auxiliary_predictions": [{"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"}, {"type": "size_segment", "segment": "small", "direction": "stronger"}, {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}], "expected_annualized_sharpe": 0.8, "expected_decay_half_life_months": 24},
{"name": "Composite2", "mechanism": "Combining momentum and value factors can help identify stocks with high expected returns. The momentum factor can capture stocks with high growth potential, while the value factor can capture stocks with low prices relative to their fundamentals.", "expression": {"terms": [{"weight": 1.0, "primitive": "Mom12m"}, {"weight": 1.0, "primitive": "EP"}], "regime": "MKT_TRAILING_12M_UP", "vol_target": false}, "auxiliary_predictions": [{"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"}, {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}, {"type": "subperiod_consistency"}], "expected_annualized_sharpe": 0.9, "expected_decay_half_life_months": 36},
{"name": "Composite3", "mechanism": "Firms with high intangible assets and low book leverage tend to have high expected returns. Combining these factors can help identify stocks with high growth potential and low financial risk.", "expression": {"terms": [{"weight": 1.0, "primitive": "IntanBM"}, {"weight": -1.0, "primitive": "BookLeverage"}], "regime": "VIX_ABOVE_TRAILING_MEDIAN", "vol_target": true}, "auxiliary_predictions": [{"type": "size_segment", "segment": "large", "direction": "weaker"}, {"type": "correlation", "primitive": "RoE", "bound": "above", "threshold": 0.3}, {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "lower"}], "expected_annualized_sharpe": 0.7, "expected_decay_half_life_months": 18},
{"name": "Composite4", "mechanism": "Combining factors that capture earnings quality and financial health can help identify stocks with high expected returns. Firms with high earnings quality and low financial risk tend to have high future returns.", "expression": {"terms": [{"weight": 1.0, "primitive": "EarningsConsistency"}, {"weight": -1.0, "primitive": "NetDebtFinance"}], "regime": null, "vol_target": false}, "auxiliary_predictions": [{"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "lower"}, {"type": "international", "region": "emerging", "direction": "opposite_sign"}, {"type": "subperiod_consistency"}], "expected_annualized_sharpe": 0.85, "expected_decay_half_life_months": 30},
{"name": "Composite5", "mechanism": "Firms with high R&D expenditures and low market beta tend to have high expected returns. Combining these factors can help identify stocks with high growth potential and low systematic risk.", "expression": {"terms": [{"weight": 1.0, "primitive": "RD"}, {"weight": -1.0, "primitive": "Beta"}], "regime": "MKT_TRAILING_12M_UP", "vol_target": true}, "auxiliary_predictions": [{"type": "size_segment", "segment": "mega", "direction": "weaker"}, {"type": "correlation", "primitive": "Mom6m", "bound": "below", "threshold": 0.3}, {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"}], "expected_annualized_sharpe": 0.95, "expected_decay_half_life_months": 42},
{"name": "Composite6", "mechanism": "Combining factors that capture profitability and investment can help identify stocks with high expected returns. Firms with high profitability and low investment tend to have high future returns.", "expression": {"terms": [{"weight": 1.0, "primitive": "OperProf"}, {"weight": -1.0, "primitive": "Investment"}], "regime": null, "vol_target": false}, "auxiliary_predictions": [{"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"}, {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}, {"type": "subperiod_consistency"}], "expected_annualized_sharpe": 0.8, "expected_decay_half_life_months": 24},
{"name": "Composite7", "mechanism": "Firms with high intangible assets and high earnings quality tend to have high expected returns. Combining these factors can help identify stocks with high growth potential and high earnings quality.", "expression": {"terms": [{"weight": 1.0, "primitive": "IntanBM"}, {"weight": 1.0, "primitive": "EarningsConsistency"}], "regime": "VIX_ABOVE_TRAILING_MEDIAN", "vol_target": true}, "auxiliary_predictions": [{"type": "size_segment", "segment": "small", "direction": "stronger"}, {"type": "correlation", "primitive": "RoE", "bound": "above", "threshold": 0.3}, {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "lower"}], "expected_annualized_sharpe": 0.85, "expected_decay_half_life_months": 30},
{"name": "Composite8", "mechanism": "Combining factors that capture financial health and profitability can help identify stocks with high expected returns. Firms with high financial health and high profitability tend to have high future returns.", "expression": {"terms": [{"weight": 1.0, "primitive": "NetPayoutYield"}, {"weight": 1.0, "primitive": "OperProf"}], "regime": null, "vol_target": false}, "auxiliary_predictions": [{"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "lower"}, {"type": "international", "region": "emerging", "direction": "opposite_sign"}, {"type": "subperiod_consistency"}], "expected_annualized_sharpe": 0.9, "expected_decay_half_life_months": 36}
]}
